#!/usr/bin/env node
/**
 * Build-time guard: verify prerender coverage.
 *
 * Fails the build loudly if any route registered in PRERENDERED_ROUTES
 * (src/lib/autoRoutes.ts, generated by scripts/generate-routes.cjs) does NOT
 * have a corresponding HTML file in dist/_prerender/.
 *
 * Why this exists (2026-07-29 incident):
 *   middleware.ts rewrites bot requests for any path in PRERENDERED_ROUTES to
 *   dist/_prerender/<path>.html. If that route is registered but the file was
 *   never generated by scripts/prerender.js, Vercel's rewrite target 404s.
 *   Regular browsers take a completely different code path (injectMetaIntoSpa,
 *   which always falls back to index.html) so they see a normal 200 page —
 *   this made the bug invisible unless you tested with a bot user-agent.
 *
 *   27 blog posts + all 25 programmatic SEO "combo" landing pages drifted out
 *   of sync this way and were returning a hard 404 to Googlebot/Bingbot while
 *   serving 200 to humans — a soft-cloaking bug that is the most likely cause
 *   of a Search Console traffic drop. This script makes that class of bug
 *   impossible to ship silently again: if route registration and prerendered
 *   HTML output ever drift apart, `npm run build` now fails instead of
 *   deploying broken routes.
 *
 * Run: node scripts/verify-prerender-coverage.cjs
 * Automatically run during: npm run build (final step)
 */

const fs = require('fs');
const path = require('path');

// This guard already runs immediately after prerender.js. Sanitize the actual
// error document first so every successful build also enforces consistent
// 404 crawler directives, removes canonical URLs, and strips page schema.
require('./postprocess-error-pages.cjs');

const PROJECT_ROOT = path.resolve(__dirname, '..');
const ROUTES_JSON = path.join(PROJECT_ROOT, 'scripts/routes.json');
const PRERENDER_DIR = path.join(PROJECT_ROOT, 'dist/_prerender');

function routeToFilePath(routePath) {
  if (routePath === '/') {
    return path.join(PRERENDER_DIR, 'index.html');
  }
  const parts = routePath.slice(1); // remove leading /
  return path.join(PRERENDER_DIR, `${parts}.html`);
}

function main() {
  if (!fs.existsSync(ROUTES_JSON)) {
    console.error(`[verify-prerender-coverage] ${ROUTES_JSON} not found — did generate-routes.cjs run?`);
    process.exit(1);
  }
  if (!fs.existsSync(PRERENDER_DIR)) {
    console.error(`[verify-prerender-coverage] ${PRERENDER_DIR} not found — did prerender.js run?`);
    process.exit(1);
  }

  const routes = JSON.parse(fs.readFileSync(ROUTES_JSON, 'utf8'));
  const missing = [];

  for (const route of routes) {
    const filePath = routeToFilePath(route);
    if (!fs.existsSync(filePath)) {
      missing.push({ route, filePath });
    }
  }

  if (missing.length > 0) {
    console.error(`\n[verify-prerender-coverage] BUILD FAILURE: ${missing.length} route(s) in PRERENDERED_ROUTES have no prerendered HTML file.`);
    console.error('[verify-prerender-coverage] These routes would return a bot-only 404 in production (soft cloaking) — see the 2026-07-29 incident notes in this script.');
    console.error('[verify-prerender-coverage] Missing routes:');
    for (const { route, filePath } of missing) {
      console.error(`  ${route}  →  ${path.relative(PROJECT_ROOT, filePath)}`);
    }
    console.error('\n[verify-prerender-coverage] Fix: either (a) add/verify the route in scripts/prerender.js so it generates HTML, or (b) remove the route from scripts/generate-routes.cjs if it should not be prerendered.\n');
    process.exit(1);
  }

  console.log(`[verify-prerender-coverage] OK — all ${routes.length} routes in PRERENDERED_ROUTES have a matching prerendered HTML file.`);
}

main();
